package br.com.marquesautodetail.api.servico;
import br.com.marquesautodetail.api.empresa.EmpresaRepository;import br.com.marquesautodetail.api.servico.dto.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class ServicoService{ private final ServicoRepository repo; private final EmpresaRepository empresas; public ServicoService(ServicoRepository repo,EmpresaRepository empresas){this.repo=repo;this.empresas=empresas;} public List<ServicoResponse> listarPorEmpresa(Long empresaId){return repo.findByEmpresaIdAndAtivoTrue(empresaId).stream().map(this::toResponse).toList();} @Transactional public ServicoResponse criar(Long empresaId,ServicoRequest r){var empresa=empresas.findById(empresaId).orElseThrow(()->new IllegalArgumentException("Empresa não encontrada")); Servico s=new Servico(); s.setEmpresa(empresa); aplicar(s,r); s.setAtivo(true); return toResponse(repo.save(s));} @Transactional public ServicoResponse atualizar(Long id,ServicoRequest r){Servico s=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Serviço não encontrado")); aplicar(s,r); return toResponse(repo.save(s));} @Transactional public void remover(Long id){Servico s=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Serviço não encontrado")); s.setAtivo(false); repo.save(s);} private void aplicar(Servico s,ServicoRequest r){ if(r.nome()!=null)s.setNome(r.nome()); if(r.descricao()!=null)s.setDescricao(r.descricao()); if(r.preco()!=null)s.setPreco(r.preco()); if(r.duracaoMinutos()!=null)s.setDuracaoMinutos(r.duracaoMinutos()); } public ServicoResponse toResponse(Servico s){return new ServicoResponse(s.getId(),s.getNome(),s.getDescricao(),s.getPreco(),s.getDuracaoMinutos(),s.getAtivo());} }
